-- Seed IR sources Stoxx 600 (sociétés européennes restantes, hors V1.7 et Stoxx EU déjà fait).
-- Généré par 20 batches WebSearch agents (12 mai 2026).
-- Inclut regulator_url par pays (FCA, AMF, BaFin, SIX, CONSOB, CNMV, AFM, FSMA, CMVM, Nasdaq Nordic, Oslo Børs, FMA, CBI, KNF, CSSF).
-- Idempotent : ON CONFLICT (ticker) DO UPDATE.

ON CONFLICT (ticker) DO UPDATE SET
  home_url = EXCLUDED.home_url,
  ir_home_url = EXCLUDED.ir_home_url,
  ir_docs_main_url = EXCLUDED.ir_docs_main_url,
  ir_docs_additional_urls = EXCLUDED.ir_docs_additional_urls,
  regulator_url = EXCLUDED.regulator_url,
  status = EXCLUDED.status,
  updated_at = now();

-- Ajout 3 stés suédoises (Wikipedia lowercase ticker form non matché en dedup initial).
-- 12 mai 2026.
ON CONFLICT (ticker) DO UPDATE SET
  home_url = EXCLUDED.home_url,
  ir_home_url = EXCLUDED.ir_home_url,
  ir_docs_main_url = EXCLUDED.ir_docs_main_url,
  ir_docs_additional_urls = EXCLUDED.ir_docs_additional_urls,
  regulator_url = EXCLUDED.regulator_url,
  status = EXCLUDED.status,
